  "news_id": "N:doc-10",
  "company_id": "U_19717",
  "headline": "Рост тарифов на 12% бьёт по вашим клиентам-перевозчикам, но поднимает цены на ваше топливо",
  "impact_type": "mixed",
  "importance": "medium",
  "confidence": "medium",
  "what_happened": [
    {"text": "Стоимость грузовых автоперевозок по России выросла на 12% с начала года из-за дефицита водителей и подорожания дизтоплива.", "origin": "fact", "source_ids": ["N:doc-10"]},
    {"text": "Логисты и интернет-магазины пересматривают тарифы доставки до пунктов выдачи заказов.", "origin": "fact", "source_ids": ["N:doc-10"]}
  ],
  "why_it_matters": [
    {"text": "Основной вид деятельности вашей компании — розничная торговля моторным топливом, а подорожание дизтоплива названо одной из причин роста тарифов: рост цен на сырьё (бензин, дизтопливо) одновременно повышает и закупочные издержки, и выручку с литра.", "origin": "ai", "source_ids": ["F:MAINOKVED_NAME", "F:RAW_MATERIALS", "N:doc-10"]},
    {"text": "Среди ваших покупателей есть компании грузового автотранспорта и ремонта автотранспорта: рост тарифов на 12% частично компенсирует им удорожание топлива, но дефицит водителей может сжимать их объёмы перевозок и, как следствие, закупки топлива у вас.", "origin": "ai", "source_ids": ["P:U_9000008", "P:U_9000025", "N:doc-10"]},
    {"text": "У компании есть кредитные продукты и факторинг: при росте закупочных цен на топливо потребность в оборотном финансировании может увеличиться, а у контрагентов-перевозчиков — вырасти кассовые разрывы.", "origin": "ai", "source_ids": ["F:CL_PRODUCT_LOA_MARK", "F:FACTORING_MARK", "N:doc-10"]}
  ],
  "consequences": [
    {"text": "Риск для выручки: если дефицит водителей сократит объёмы перевозок у клиентов из грузового автотранспорта, их потребление топлива снизится — это прямой риск для продаж АЗС-бизнеса.", "kind": "risk", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["P:U_9000008", "N:doc-10"]},
    {"text": "Возможность: подорожание дизтоплива и бензина позволяет пересматривать розничные цены вслед за закупочными; при стабильных поставках от НПЗ и нефтебаз маржа может удержаться или вырасти.", "kind": "opportunity", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["F:KEY_SUPPLIERS", "F:RAW_MATERIALS", "N:doc-10"]},
    {"text": "Фактор неопределённости: дальнейшая динамика цен на дизтопливо — главный параметр, от которого зависит и ваша маржа, и платёжеспособность клиентов-перевозчиков; рост тарифов на 12% говорит, что издержки в отрасли продолжают раскручиваться.", "kind": "factor", "level": "medium", "horizon": "medium", "origin": "ai", "source_ids": ["N:doc-10"]}
  ],
  "actions": [
    {"text": "Проверить структуру выручки по сегментам клиентов: какая доля приходится на транспортные компании и автопарки, и насколько их закупки чувствительны к росту цен на топливо.", "type": "question", "bank_product": null, "source_ids": ["P:U_9000008", "P:U_9000025"]},
    {"text": "Сценарий: если цены на дизтопливо продолжат расти, зафиксировать условия закупок с нефтебазами и НПЗ на горизонт 3–6 месяцев, чтобы не терять маржу при резких скачках.", "type": "scenario", "bank_product": null, "source_ids": ["F:KEY_SUPPLIERS", "N:doc-10"]},
    {"text": "Оценить лимит факторинга: рост тарифов и цен на топливо увеличивает оборотный капитал клиентов-перевозчиков — их отсрочки платежа могут стать дороже для вашего денежного потока.", "type": "action", "bank_product": "факторинг", "source_ids": ["F:FACTORING_MARK", "P:U_9000008"]}
  ],
  "bank_view": [],
  "company_features_used": ["F:MAINOKVED_NAME", "F:RAW_MATERIALS", "F:KEY_SUPPLIERS", "F:KEY_CLIENTS", "F:CL_PRODUCT_LOA_MARK", "F:FACTORING_MARK", "P:U_9000008", "P:U_9000025"],
  "data_gaps": [
    "Нет аналитики Альфа-Банка по рынку грузоперевозок и ценам на топливо — имеющиеся фрагменты про экспорт и импорт к событию напрямую не относятся",
    "Нет данных о доле выручки, приходящейся на клиентов из грузового автотранспорта",
    "Нет данных о марже компании и условиях закупочных контрактов с нефтебазами"
  ]
}
